/// <summary>
/// COC generateFromCommon
/// </summary>
/// <param name = "_record">record</param>
public void generateFromCommon(Common _record)
{
    EcoResProductTranslation lEcoResProductTranslation;

    next generateFromCommon(_record);

    lEcoResProductTranslation = EcoResProductTranslation::findByProductLanguage(inventTable.Product,CompanyInfo::languageId());

    partObject.Note = lEcoResProductTranslation.NDXProductName2;
    partObject.Note2 = lEcoResProductTranslation.Description;
}

